    "statement": "Leia o texto para responder às questões 09 e 10.\n\nAlthough often used interchangeably by the general public, there are crucial distinctions between the terms “refugee” and “migrant”:\n\nRefugee Refugees are persons who are outside their country of origin for reasons of feared persecution, conflict, generalized violence, or other circumstances that have seriously disturbed public order and, as a result, require international protection. The refugee definition can be found in the 1951 Convention and regional refugee instruments, as well as United Nations Commissioner for Refugees’ (UNHCR) Statute.\n\nMigrant While there is no formal legal definition of an international migrant, most experts agree that an international migrant is someone who changes his or her country of usual residence, independently of the reason for migration or legal status. Generally, a distinction is made between short-term or temporary migration, covering movements with a duration between three and 12 months, and long-term or permanent migration, referring to a change of country of residence for a duration of one year or more.\n\n(https://refugeesmigrants.un.org. Adaptado.)\n\nThe text intends to",
