    "statement": "Calcula-se que, no século I a.C., os escravizados constituíam cerca de 30% de toda a população da península itálica. Imigrados à força, eles ocuparam as cidades em todos os ofícios. Mas foi no campo que sua utilização foi mais intensa. A falta de direitos desses indivíduos, a possibilidade de sua total opressão, seu trabalho em equipe, sua falta de família para alimentar, permitiram um aumento notável da exploração do excedente de trabalho.\n\n(Norberto Luiz Guarinello. História Antiga, 2020. Adaptado.)\n\nNo contexto da expansão territorial da República romana, o excerto apresenta características de uma sociedade",
