    "difficulty": "Média",
    "statement": "O consumidor em uma sociedade de consumo é uma criatura acentuadamente diferente dos consumidores de quaisquer outras sociedades até aqui. Se os nossos ancestrais filósofos, poetas e pregadores morais refletiram se o homem trabalha para viver ou vive para trabalhar, o dilema sobre o qual mais se cogita hoje em dia é se é necessário consumir para viver ou se o homem vive para poder consumir. Isto é, se ainda somos capazes e sentimos a necessidade de distinguir aquele que vive daquele que consome.\n\n(Zygmunt Bauman. Globalização: as consequências humanas, 1999.)\n\nDe acordo com o excerto, a sociedade atual, chamada por Bauman de pós-moderna, diferencia-se das suas predecessoras, pois",
