    "statement": "O movimento operário veio à tona, no governo Geisel [1974-1979], com novo ímpeto e novas feições. A reconstrução do sindicalismo populista era inviável porque o regime [militar] não se assentava, nem pretendia se assentar, no movimento operário organizado. [...] O eixo mais combativo se deslocou das empresas públicas para a indústria automobilística, que tinha sido um setor pouco atuante até 1964. A grande concentração de trabalhadores em um pequeno número de empresas e a concentração geográfica no ABC paulista foram fatores materiais importantes para a organização do novo movimento operário.\n\n(Boris Fausto. História do Brasil, 2007.)\n\nUma característica desse novo movimento operário que o diferenciava do sindicalismo populista foi a",
