    "statement": "Um estudo publicado pela rede MapBiomas mostra que Manaus é a cidade com maior expansão das áreas urbanizadas em assentamentos precários no país. Segundo o MapBiomas, em 1985 a capital do Amazonas tinha uma área de risco com ocupação urbana de aproximadamente 523 hectares. Em 2021 esse número chegou a 1 841 hectares, um aumento de aproximadamente 1 319 hectares, o que equivale a 10 mil campos de futebol. Manaus, sozinha, concentrou mais de 36% de toda a ocupação de áreas de risco no estado. No total, 50 dos 63 municípios do estado do Amazonas possuem alguma ocupação em áreas de risco.\n\n(Pedro Lacerda. “Manaus sofre com expansão urbana em assentamentos\n\nprecários”. https://agenciabrasil.ebc.com.br, 18.03.2023. Adaptado.)\n\nO contexto descrito no excerto configura, no espaço urbano, a formação do processo de",
