    "statement": "Conhecido internacionalmente como o Regime de Ozônio, o arcabouço multilateral de proteção à camada de ozônio é constituído pela Convenção de Viena para Proteção da Camada de Ozônio (1985), por um conjunto de medidas que tratam sobre as substâncias que destroem essa camada (1987), e pelas suas emendas subsequentes. Da confirmação da existência de um buraco na camada de ozônio estratosférico sobre a Antártida em 1982, causado por gases artificiais compostos de cloro, flúor, carbono e hidrogênio, passou-se ao início do declínio desse fenômeno a partir de 2006. Estima-se que essa camada de ozônio estará plenamente regenerada até meados do século XXI, caso não haja retrocesso nas atuais políticas implementadas internacionalmente.\n\n(Paulo Cézar R. Braga et al. In: Wânia Duleba e\n\nRubens Barbosa (orgs.). Diplomacia Ambiental, 2022. Adaptado.)\n\nO conjunto de medidas adotado em 1987, após a Convenção de Viena, denomina-se",
