    "difficulty": "Difícil",
    "statement": "O agronegócio brasileiro é responsável por mais de um terço das exportações da balança comercial. Estima-se que, a cada R$ 3,00 gerados na economia nacional, R$ 1,00 venha da agroindústria. Além disso, o setor é responsável por gerar 37% dos empregos criados. Esse desempenho coloca o país em perspectiva de na próxima década ser o maior produtor de commodities como farelo de soja, cana de açúcar, café e outros produtos da pecuária.\n\nÉ fato que o crescimento econômico proporciona uma melhoria nas condições sociais de um país. Mas precisamos avaliar também a que custos. Além do desmatamento, a expansão do agronegócio na Amazônia desperta outras preocupações que precisam e devem ser consideradas, tais como: aumento da pressão sobre a biodiversidade, aquecimento global, diminuição das áreas preservadas e, mais recentemente, até a segurança alimentar.\n\n(https://portalamazonia.com. Adaptado.)\n\nA respeito do agronegócio na Amazônia, o excerto defende, para a região,",
